package com.wattscape.asset;
import com.wattscape.common.BaseEntity; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDate; import java.util.UUID;
@Entity @Table(name="assets",uniqueConstraints=@UniqueConstraint(name="uq_asset_org_source",columnNames={"organization_id","source_id"}))
public class Asset extends BaseEntity {
 @Column(name="organization_id",nullable=false) private UUID organizationId; @Column(name="site_id",nullable=false) private UUID siteId; @Column(name="floor_id",nullable=false) private UUID floorId; @Column(name="room_id") private UUID roomId;
 @Column(name="system_name",length=120) private String systemName; @Column(name="asset_class",nullable=false,length=40) private String assetClass; @Column(nullable=false,length=160) private String name; @Column(length=120) private String manufacturer; @Column(length=120) private String model; @Column(length=120) private String serial; @Column(name="commission_date") private LocalDate commissionDate;
 @Column(nullable=false,length=24) private String status="commissioning"; @Column(nullable=false,length=16) private String criticality="medium"; @Column(length=160) private String owner; @Column(name="source_id",nullable=false,length=120) private String sourceId; @Column(name="power_kw",precision=14,scale=3) private BigDecimal powerKw; @Column(name="water_flow_lpm",precision=14,scale=3) private BigDecimal waterFlowLpm;
 protected Asset(){} public Asset(UUID org,UUID site,UUID floor,UUID room,String systemName,String assetClass,String name,String sourceId,String manufacturer,String model,String serial,LocalDate commissioningDate,String criticality,BigDecimal powerKw,BigDecimal waterFlowLpm){this.organizationId=org;this.siteId=site;this.floorId=floor;this.roomId=room;this.systemName=systemName;this.assetClass=assetClass;this.name=name;this.sourceId=sourceId;this.manufacturer=manufacturer;this.model=model;this.serial=serial;this.commissionDate=commissioningDate;this.criticality=criticality;this.powerKw=powerKw;this.waterFlowLpm=waterFlowLpm;}
 public UUID getOrganizationId(){return organizationId;} public UUID getSiteId(){return siteId;} public UUID getFloorId(){return floorId;} public UUID getRoomId(){return roomId;} public String getSystemName(){return systemName;} public String getAssetClass(){return assetClass;} public String getName(){return name;} public String getManufacturer(){return manufacturer;} public String getModel(){return model;} public String getSerial(){return serial;} public LocalDate getCommissionDate(){return commissionDate;} public String getStatus(){return status;} public String getCriticality(){return criticality;} public String getOwner(){return owner;} public String getSourceId(){return sourceId;} public BigDecimal getPowerKw(){return powerKw;} public BigDecimal getWaterFlowLpm(){return waterFlowLpm;}
}
